def formula(arr,r,c):
 H,W=len(arr),len(arr[0]); o=[[0]*W for _ in range(H)]
 for i in range(H):
  for j in range(W):
   if i==r or j==c: o[i][j]=3; continue
   y=abs(i-r);x=abs(j-c)
   on=(x<=y or x%2==0) if y%2==0 else (x>y and x%2==0)
   if on:o[i][j]=4
 return o
for arr,r,c in [(rows10,4,6),(rows20,5,7)]:
 ff=formula(arr,r,c)
 bad=[(i,j,arr[i][j],ff[i][j]) for i in range(len(arr)) for j in range(len(arr[0])) if arr[i][j]!=ff[i][j]]
 print(len(bad), bad[:30])

