# Compare ring parity using other natural centers to output pairs.
def acc(arr, a, b):
 H,W=len(arr),len(arr[0]); bad=[]
 for i in range(H):
  for j in range(W):
   if arr[i][j]==3: continue
   pred=4 if max(abs(i-a),abs(j-b))%2==0 else 0
   if pred!=arr[i][j]:bad.append((i,j))
 return len(bad),bad[:5]
